options(stringsAsFactors=FALSE,survey.lonely.psu='adjust');Sys.setenv(OPENBLAS_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1');root<-'./TB_metabolome_exposome_20261115_2130';out<-'./系统复审与优化_20261116';.libPaths(c(file.path(root,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));suppressPackageStartupMessages({library(survey);library(data.table)});set.seed(20261116)
a<-as.data.frame(readRDS(file.path(root,'analysis_MWAS_ExWAS/derived/analysis_2011-2012.rds')));w<-as.data.frame(readRDS(file.path(root,'output/2011-2012/NHANES_2011-2012_full_population_wide_TBflags.rds')));stopifnot(!anyDuplicated(a$SEQN),!anyDuplicated(w$SEQN));w<-w[match(a$SEQN,w$SEQN),];stopifnot(all(a$SEQN==w$SEQN));o<-readRDS(file.path(root,'analysis_MWAS_ExWAS/stage3_integrated_exposome_metabolome/derived/01_classification.rds'));q<-as.data.frame(o$qc);v<-as.data.frame(o$var_map);q<-q[q$cycle=='2011-2012' & q$s3_class%in%c('A_exposome','B_host_metabolome','C_clinical_auxiliary'),];v<-v[v$cycle=='2011-2012',];v<-v[match(q$variable,v$variable),];stopifnot(all(q$variable==v$variable),!anyDuplicated(q$variable));q$lc_variable<-v$lc_variable;q$lc_accepted<-v$lc_accepted
# Keep 30 public FAS_G endogenous fatty acid measurements as the metabolic discovery layer.
fa<-c('LBXCAP','LBXLAR','LBXMR1','LBXPEN','LBXPM1','LBXMRG','LBXST1','LBXAR1','LBXDA1','LBXTSA','LBXLG1','LBXML1','LBXPL1','LBXVC1','LBXOL1','LBXEN1','LBXNR1','LBXLNA','LBXALN','LBXGLA','LBXSD1','LBXED1','LBXHGL','LBXET1','LBXARA','LBXEPA','LBXDTA','LBXDP3','LBXDP6','LBXDHA');q$layer<-ifelse(q$s3_class=='A_exposome' | q$class=='Caffeine metabolites','exposome',ifelse(q$variable%in%fa,'fatty_acids',ifelse(q$s3_class=='B_host_metabolome','nutrition_biomarkers','clinical_auxiliary')));q$classification_note<-ifelse(q$class=='Caffeine metabolites','diet-derived xenobiotic markers, not endogenous host metabolites',ifelse(q$variable%in%fa,'targeted endogenous fatty acids',ifelse(q$layer=='nutrition_biomarkers','nutrition-related biomarkers, not automatically endogenous metabolites','')));q<-q[order(q$layer,q$class,q$variable),];write.csv(q,file.path(out,'数据表/01_candidate_registry.csv'),row.names=FALSE,na='');cat('registry',paste(names(table(q$layer)),table(q$layer),collapse='; '),'\n')
a$tb_history<-ifelse(as.numeric(w$TBQ040)==1,1L,ifelse(as.numeric(w$TBQ040)==2,0L,NA));a$tb_house<-ifelse(as.numeric(w$TBQ060)==1,1L,ifelse(as.numeric(w$TBQ060)==2,0L,NA));a$tst_mm<-as.numeric(w$TBDRUIND);a$birth<-factor(a$foreign_born,levels=c(0,1),labels=c('US','NonUS'));a$smoking<-factor(a$smoking);a$adult<-a$age>=20;a$log_ucr<-ifelse(is.finite(a$urine_creat)&a$urine_creat>0,log2(a$urine_creat),NA);a$group<-ifelse(!is.na(a$QFT)&!is.na(a$tst_mm),ifelse(a$QFT==0&a$tst_mm<10,'Q0T0',ifelse(a$QFT==1&a$tst_mm<10,'Q1T0',ifelse(a$QFT==0&a$tst_mm>=10,'Q0T1','Q1T1'))),NA)
cv<-c('age','sex_male','race','educ','PIR','birth','smoking');pairs<-list(primary_Q1T0_vs_Q0T1=c('Q0T1','Q1T0'),secondary_Q1T0_vs_Q0T0=c('Q0T0','Q1T0'),secondary_Q0T1_vs_Q0T0=c('Q0T0','Q0T1'),secondary_Q1T1_vs_Q0T0=c('Q0T0','Q1T1'))
run<-function(i,contrast,variant='main'){qr<-q[i,];x<-qr$variable;wt<-qr$weight;ct<-pairs[[contrast]];r<-data.frame(variable=x,label=qr$label,layer=qr$layer,family=qr$class,source_table=qr$source_table,weight=wt,contrast=contrast,variant=variant,mode=NA_character_,scale=NA_character_,n=NA_integer_,n_case=NA_integer_,n_reference=NA_integer_,n_eff=NA_real_,n_psu=NA_integer_,n_strata=NA_integer_,df=NA_real_,df_residual=NA_real_,b=NA_real_,se=NA_real_,OR=NA_real_,low=NA_real_,high=NA_real_,p=NA_real_,status='error',message='',stringsAsFactors=FALSE)
msg<-character();tryCatch(withCallingHandlers({if(!x%in%names(a))stop('variable missing');if(!wt%in%names(a)||is.na(wt))stop('official weight missing');d<-a;val<-as.numeric(d[[x]]);iscens<-!is.na(qr$detection_category)&&qr$detection_category=='<50% detected';if(iscens){lc<-qr$lc_variable;if(is.na(lc)||!nzchar(lc)||!isTRUE(qr$lc_accepted)||!lc%in%names(w))stop('verified LOD comment code unavailable');code<-as.numeric(w[[lc]]);d$.x<-ifelse(code%in%c(0,1),as.integer(code==0),NA_real_);r$mode<-'LOD_detection';r$scale<-'detected vs below LOD'}else if(qr$transform=='log2'){d$.x<-ifelse(is.finite(val)&val>0,log2(val),NA_real_);r$mode<-'log2';r$scale<-'per doubling'}else {d$.x<-val;r$mode<-'linear';r$scale<-'per measured unit'}
 cov<-cv;if(isTRUE(qr$smoking_biomarker))cov<-setdiff(cov,'smoking');if(isTRUE(qr$urinary))cov<-c(cov,'log_ucr');if(variant=='no_smoking')cov<-setdiff(cov,'smoking');if(variant=='add_contact'){cov<-c(cov,'tb_house')};if(variant=='TST_gt10'){d$group<-ifelse(!is.na(d$QFT)&!is.na(d$tst_mm),ifelse(d$QFT==0&d$tst_mm<=10,'Q0T0',ifelse(d$QFT==1&d$tst_mm<=10,'Q1T0',ifelse(d$QFT==0&d$tst_mm>10,'Q0T1','Q1T1'))),NA)};if(variant=='TST_ge15'){d$group<-ifelse(!is.na(d$QFT)&!is.na(d$tst_mm),ifelse(d$QFT==0&d$tst_mm<15,'Q0T0',ifelse(d$QFT==1&d$tst_mm<15,'Q1T0',ifelse(d$QFT==0&d$tst_mm>=15,'Q0T1','Q1T1'))),NA)}
 d$.y<-ifelse(d$group==ct[2],1,ifelse(d$group==ct[1],0,NA));mask<-d$adult & !is.na(d$.y) & complete.cases(d[,c('.x',cov),drop=FALSE]) & is.finite(d[[wt]]) & d[[wt]]>0;if(variant=='exclude_active_TB')mask<-mask & !is.na(d$tb_history) & d$tb_history==0;mask[is.na(mask)]<-FALSE;r$n<-sum(mask);r$n_case<-sum(mask&d$.y==1,na.rm=TRUE);r$n_reference<-sum(mask&d$.y==0,na.rm=TRUE);if(r$n_case<10||r$n_reference<10)stop('fewer than 10 events or reference observations');if(length(unique(d$.x[mask]))<2)stop('exposure has no variation');ww<-d[[wt]][mask];r$n_eff<-sum(ww)^2/sum(ww^2);r$n_psu<-length(unique(paste(d$SDMVSTRA[mask],d$SDMVPSU[mask])));r$n_strata<-length(unique(d$SDMVSTRA[mask]));allw<-is.finite(d[[wt]]) & d[[wt]]>0 & !is.na(d$SDMVSTRA)&!is.na(d$SDMVPSU);d$.dom<-mask;design<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=as.formula(paste0('~',wt)),nest=TRUE,data=d[allw,,drop=FALSE]);sub<-subset(design,.dom);r$df<-degf(sub);f<-as.formula(paste('.y ~',paste(c('.x',cov),collapse='+')));fit<-svyglm(f,sub,family=quasibinomial());r$df_residual<-fit$df.residual;b<-unname(coef(fit)['.x']);se<-unname(sqrt(diag(vcov(fit)))['.x']);if(!is.finite(b)||!is.finite(se)||se<=0||r$df<=0)stop('coefficient or variance not estimable');r$b<-b;r$se<-se;r$OR<-exp(b);r$low<-exp(b-qt(.975,r$df_residual)*se);r$high<-exp(b+qt(.975,r$df_residual)*se);r$p<-2*pt(-abs(b/se),r$df_residual);r$status<-if(!isTRUE(fit$converged)||abs(b)>5||se>2)'unstable' else 'ok'
},warning=function(w){msg<<-c(msg,conditionMessage(w));invokeRestart('muffleWarning')}),error=function(e)msg<<-c(msg,conditionMessage(e)));r$message<-paste(unique(msg),collapse=' | ');r}
# Pre-defined broad sensitivity variants for every exposure and host FA, with identical FDR families within variant.
sens<-list();for(vr in c('TST_gt10','TST_ge15','exclude_active_TB','no_smoking','add_contact')){cat('sensitivity',vr,'\n');flush.console();for(i in which(q$layer%in%c('exposome','fatty_acids','nutrition_biomarkers')))sens[[length(sens)+1]]<-run(i,'primary_Q1T0_vs_Q0T1',vr)};s<-do.call(rbind,sens);s$p_for_FDR<-ifelse(s$status=='ok' & is.finite(s$p),s$p,1);s$q_global<-NA_real_;for(layer in unique(s$layer))for(vr in unique(s$variant)){ii<-which(s$layer==layer&s$variant==vr);s$q_global[ii]<-p.adjust(s$p_for_FDR[ii],'BH',n=length(ii))};write.csv(s,file.path(out,'数据表/16_敏感性全部残余自由度.csv'),row.names=FALSE,na='')
cat('DONE corrected sensitivity\n')
